import React from 'react';

/**
 * The Walking Studio scene: an original illustration drawn by hand for NUQTA.
 *
 * Three rules keep this readable and cheap:
 *
 * 1. Everything is CSS. Parallax is one `translateX` loop per depth band and the walk
 *    cycle is baked rotation keyframes (generated by `scripts/walk-cycle.mjs`). No
 *    animation library, no per-frame React renders, and a single
 *    `prefers-reduced-motion` block turns all of it off.
 *
 * 2. Each depth band is a tile repeated side by side, and a band animates by exactly one
 *    tile width. The frame at 100% is therefore pixel-identical to 0% and the loop has no
 *    seam. The previous version drifted a few pixels and snapped back, which is what made
 *    the landscape read as static.
 *
 * 3. An element animated by CSS must not also carry a `transform` attribute: the CSS
 *    `transform` property wins and the attribute offset is silently dropped. So offsets
 *    live in a static wrapper `<g>` and the animated `<g>` sits inside it with none.
 *
 * The walker stands still while the world moves backwards past it.
 */

interface SceneProps {
  /** True while the walk is running — the CSS animation is applied via this class. */
  walking: boolean;
  className?: string;
  /** Decorative by default; the surrounding section provides the accessible name. */
  ariaHidden?: boolean;
}

const P = {
  sun: 'var(--walk-sun)',
  ridgeFar: 'var(--walk-ridge-far)',
  ridgeNear: 'var(--walk-ridge-near)',
  canopy: 'var(--walk-canopy)',
  canopyDeep: 'var(--walk-canopy-deep)',
  trunk: 'var(--walk-trunk)',
  meadow: 'var(--walk-meadow)',
  meadowDeep: 'var(--walk-meadow-deep)',
  path: 'var(--walk-path)',
  pathEdge: 'var(--walk-path-edge)',
  petal: 'var(--walk-petal)',
  petalAlt: 'var(--walk-petal-alt)',
  stem: 'var(--walk-stem)',
  cloud: 'var(--walk-cloud)',
  bird: 'var(--walk-bird)',
  skin: 'var(--walk-skin)',
  hair: 'var(--walk-hair)',
  shirt: 'var(--walk-shirt)',
  shirtShade: 'var(--walk-shirt-shade)',
  trousers: 'var(--walk-trousers)',
  shoe: 'var(--walk-shoe)',
  scarf: 'var(--walk-scarf)'
};

/** Ground line: the walker's soles and the path both sit here. */
const GROUND = 366;
/** The walker's x position. Fixed — the landscape moves instead. */
const WALKER_X = 400;
/** Hip joint height above the ground; matches HIP in scripts/walk-cycle.mjs. */
const HIP_Y = -54.47;
/** Thigh and shin lengths; match L1/L2 in scripts/walk-cycle.mjs. */
const THIGH = 30;
const SHIN = 26;
const VIEW_W = 800;

/**
 * Repeats a band's artwork enough times that it still covers the frame after the band
 * has slid a full tile to the left.
 */
const Tile: React.FC<{ width: number; children: React.ReactNode }> = ({ width, children }) => {
  const copies = Math.ceil(VIEW_W / width) + 1;
  return (
    <>
      {Array.from({ length: copies }, (_, i) => (
        <g key={i} transform={`translate(${i * width} 0)`}>
          {children}
        </g>
      ))}
    </>
  );
};

/** A tuft of grass, reused across the ground bands. */
const Tuft: React.FC<{ x: number; y: number; s?: number; fill: string }> = ({ x, y, s = 1, fill }) => (
  <g transform={`translate(${x} ${y}) scale(${s})`} stroke={fill} strokeWidth="2.2" strokeLinecap="round" fill="none">
    <path d="M0 0 q1 -11 4 -16" />
    <path d="M4 0 q0 -10 -3 -14" />
    <path d="M8 0 q2 -9 6 -13" />
  </g>
);

/**
 * A five-petal flower. The animated group's origin is the base of the stem, so the sway
 * pivots where the flower meets the ground.
 */
const Flower: React.FC<{ x: number; y: number; s?: number; alt?: boolean; delay?: string }> = ({
  x,
  y,
  s = 1,
  alt = false,
  delay = '0s'
}) => (
  <g transform={`translate(${x} ${y}) scale(${s})`}>
    <g className="walk-flower" style={{ ['--flower-delay' as string]: delay }}>
      <path d="M0 0 q2 -12 0 -20" stroke={P.stem} strokeWidth="2" fill="none" strokeLinecap="round" />
      <g transform="translate(0 -22)">
        {[0, 72, 144, 216, 288].map((deg) => (
          <ellipse
            key={deg}
            cx="0"
            cy="-4.6"
            rx="3.1"
            ry="4.9"
            fill={alt ? P.petalAlt : P.petal}
            transform={`rotate(${deg})`}
          />
        ))}
        <circle r="2.1" fill={P.petalAlt} />
      </g>
    </g>
  </g>
);

/** A tree. The whole tree sways about its trunk base, so roots stay planted. */
const Tree: React.FC<{ x: number; y: number; s?: number; shade?: number }> = ({ x, y, s = 1, shade = 1 }) => (
  <g transform={`translate(${x} ${y}) scale(${s})`}>
    <g className="walk-tree">
      <path d="M0 0 q-4 -34 2 -54" stroke={P.trunk} strokeWidth="7" fill="none" strokeLinecap="round" />
      <ellipse cx="2" cy="-80" rx="46" ry="38" fill={P.canopyDeep} opacity={shade} />
      <ellipse cx="-18" cy="-92" rx="30" ry="26" fill={P.canopy} opacity={shade} />
      <ellipse cx="22" cy="-88" rx="26" ry="22" fill={P.canopy} opacity={shade * 0.9} />
      <ellipse cx="2" cy="-104" rx="24" ry="20" fill={P.canopy} opacity={shade * 0.75} />
    </g>
  </g>
);

/**
 * One leg. Each joint is its own group positioned by a static wrapper, and the animated
 * group inside carries no transform attribute, so the rotation pivots exactly at the
 * joint. The shoe is drawn above the contact point so the sole meets the ground.
 */
const Leg: React.FC<{ side: 'near' | 'far' }> = ({ side }) => {
  const far = side === 'far';
  const opacity = far ? 0.82 : 1;
  return (
    <g className={`walk-leg walk-leg--${side}`} transform={`translate(0 ${HIP_Y})`}>
      <g className="walk-thigh-bone">
        <path
          className="walk-thigh"
          d={`M0 0 q${far ? -1 : 1} 16 0 ${THIGH}`}
          stroke={P.trousers}
          strokeWidth={far ? 11 : 11.5}
          strokeLinecap="round"
          fill="none"
          opacity={opacity}
        />
        <g transform={`translate(0 ${THIGH})`}>
          <g className="walk-shin-bone">
            <path
              className="walk-shin"
              d={`M0 0 q${far ? 1 : -1} 14 0 ${SHIN}`}
              stroke={P.trousers}
              strokeWidth={far ? 9.5 : 10}
              strokeLinecap="round"
              fill="none"
              opacity={opacity}
            />
            <g transform={`translate(0 ${SHIN})`}>
              <g className="walk-foot-bone">
                <path
                  className="walk-foot"
                  d="M-6 0 q0 -6 7 -7 q9 -1 11 5 q1 3 -4 3 q-8 -1 -14 -1 Z"
                  fill={P.shoe}
                  opacity={opacity}
                />
              </g>
            </g>
          </g>
        </g>
      </g>
    </g>
  );
};

/** One arm, hanging from the shoulder; the elbow is a nested joint. */
const Arm: React.FC<{ side: 'near' | 'far' }> = ({ side }) => {
  const far = side === 'far';
  const dir = far ? -1 : 1;
  return (
    <g className={`walk-arm walk-arm--${side}`} transform="translate(0 -84)">
      <g className="walk-arm-swing">
        <path
          className="walk-upper-arm"
          d={`M0 0 q${dir} 16 ${dir} 26`}
          stroke={far ? P.shirtShade : P.shirt}
          strokeWidth={far ? 8.5 : 9}
          strokeLinecap="round"
          fill="none"
        />
        <g transform={`translate(${dir} 26)`}>
          <g className="walk-forearm-group">
            <path
              className="walk-forearm"
              d={`M0 0 q${dir} 14 ${-dir} 24`}
              stroke={P.skin}
              strokeWidth={far ? 7 : 7.5}
              strokeLinecap="round"
              fill="none"
            />
          </g>
        </g>
      </g>
    </g>
  );
};

export const WalkingScene: React.FC<SceneProps> = ({ walking, className = '', ariaHidden = true }) => (
  <svg
    className={`walk-scene ${walking ? 'is-walking' : 'is-idle'} ${className}`}
    viewBox={`0 0 ${VIEW_W} 420`}
    role={ariaHidden ? 'presentation' : 'img'}
    aria-hidden={ariaHidden ? 'true' : undefined}
    preserveAspectRatio="xMidYMax slice"
  >
    <defs>
      <linearGradient id="walk-sky" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0%" stopColor="var(--walk-sky-top)" />
        <stop offset="100%" stopColor="var(--walk-sky-bottom)" />
      </linearGradient>
      <linearGradient id="walk-ground" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0%" stopColor={P.meadow} />
        <stop offset="100%" stopColor={P.meadowDeep} />
      </linearGradient>
      <radialGradient id="walk-sun-glow" cx="50%" cy="50%" r="50%">
        <stop offset="0%" stopColor={P.sun} stopOpacity="0.5" />
        <stop offset="70%" stopColor={P.sun} stopOpacity="0.12" />
        <stop offset="100%" stopColor={P.sun} stopOpacity="0" />
      </radialGradient>
    </defs>

    {/* Sky and sun stay fixed: scrolling the sky reads as the world tilting. */}
    <rect x="0" y="0" width={VIEW_W} height="420" fill="url(#walk-sky)" />
    <circle cx="648" cy="86" r="88" fill="url(#walk-sun-glow)" />
    <circle className="walk-sun" cx="648" cy="86" r="29" fill={P.sun} opacity="0.9" />

    {/* Clouds — the slowest band. */}
    <g className="walk-band walk-band--clouds">
      <Tile width={400}>
        <g opacity="0.85">
          <ellipse cx="90" cy="84" rx="52" ry="20" fill={P.cloud} />
          <ellipse cx="126" cy="74" rx="34" ry="17" fill={P.cloud} opacity="0.9" />
          <ellipse cx="58" cy="76" rx="26" ry="13" fill={P.cloud} opacity="0.75" />
        </g>
        <g opacity="0.7">
          <ellipse cx="290" cy="52" rx="42" ry="15" fill={P.cloud} />
          <ellipse cx="318" cy="44" rx="26" ry="12" fill={P.cloud} opacity="0.8" />
        </g>
      </Tile>
    </g>

    {/* Two ridge bands at different speeds give the horizon real depth. */}
    <g className="walk-band walk-band--ridge-far">
      <Tile width={VIEW_W}>
        <path
          d="M0 240 L74 204 L132 222 L196 182 L262 216 L330 190 L392 218 L470 184 L540 214 L610 188 L690 218 L760 196 L800 212 L800 300 L0 300 Z"
          fill={P.ridgeFar}
          opacity="0.5"
        />
      </Tile>
    </g>
    <g className="walk-band walk-band--ridge-near">
      <Tile width={VIEW_W}>
        <path
          d="M0 262 L64 236 L128 254 L200 228 L272 252 L352 230 L430 254 L512 232 L590 254 L668 234 L744 256 L800 242 L800 320 L0 320 Z"
          fill={P.ridgeNear}
          opacity="0.72"
        />
      </Tile>
    </g>

    {/* Birds hold their screen position; they are not part of the ground parallax. */}
    <g fill="none" stroke={P.bird} strokeWidth="2" strokeLinecap="round" opacity="0.45">
      <path className="walk-bird walk-bird--a" d="M330 96 q8 -7 16 0 q8 -7 16 0" />
      <path className="walk-bird walk-bird--b" d="M392 74 q6 -5 12 0 q6 -5 12 0" />
      <path className="walk-bird walk-bird--c" d="M272 120 q6 -5 12 0 q6 -5 12 0" />
    </g>

    {/* Far trees, behind the meadow. */}
    <g className="walk-band walk-band--trees-far">
      <Tile width={400}>
        <Tree x={40} y={300} s={0.72} shade={0.62} />
        <Tree x={250} y={306} s={0.62} shade={0.55} />
        <Tree x={340} y={298} s={0.8} shade={0.68} />
      </Tile>
    </g>

    {/* The meadow is the ground plane; it has no features to betray its speed. */}
    <path d="M0 286 Q200 268 400 280 Q600 292 800 274 L800 420 L0 420 Z" fill="url(#walk-ground)" />

    {/* Mid-ground trees, rooted on the meadow. */}
    <g className="walk-band walk-band--trees">
      <Tile width={VIEW_W}>
        <Tree x={110} y={318} s={1.05} />
        <Tree x={700} y={322} s={1.15} />
        <Tree x={420} y={314} s={0.8} shade={0.8} />
      </Tile>
    </g>

    {/* The path shares the walker's speed, so the soles stay planted on it. */}
    <g className="walk-band walk-band--path">
      <Tile width={400}>
        <path
          d={`M0 ${GROUND + 8} Q100 ${GROUND - 6} 200 ${GROUND + 2} Q300 ${GROUND + 10} 400 ${GROUND + 8} L400 420 L0 420 Z`}
          fill={P.path}
          opacity="0.9"
        />
        <path
          d={`M0 ${GROUND + 8} Q100 ${GROUND - 6} 200 ${GROUND + 2} Q300 ${GROUND + 10} 400 ${GROUND + 8}`}
          fill="none"
          stroke={P.pathEdge}
          strokeWidth="3"
          opacity="0.45"
        />
        <ellipse cx="120" cy={GROUND + 22} rx="16" ry="3.4" fill={P.pathEdge} opacity="0.3" />
        <ellipse cx="300" cy={GROUND + 34} rx="20" ry="4" fill={P.pathEdge} opacity="0.26" />
      </Tile>
    </g>

    {/* Flowers and grass on the walking plane. */}
    <g className="walk-band walk-band--flowers">
      <Tile width={400}>
        <Flower x={62} y={GROUND + 4} s={1} delay="0s" />
        <Flower x={148} y={GROUND + 20} s={0.85} alt delay="-1.1s" />
        <Flower x={236} y={GROUND + 2} s={1.1} delay="-2.2s" />
        <Flower x={330} y={GROUND + 16} s={0.9} alt delay="-0.6s" />
        <Tuft x={24} y={GROUND + 26} fill={P.meadowDeep} s={0.9} />
        <Tuft x={270} y={GROUND + 30} fill={P.meadowDeep} s={0.8} />
      </Tile>
    </g>

    {/* ---------- the walker ---------- */}
    <g className="walk-character" transform={`translate(${WALKER_X} ${GROUND})`}>
      <ellipse className="walk-shadow" cx="0" cy="0" rx="26" ry="5.5" fill="var(--walk-shadow)" opacity="0.26" />

      <g className="walk-figure">
        <Arm side="far" />
        <Leg side="far" />

        {/* torso */}
        <g className="walk-torso">
          <path d="M-11 -96 q11 -7 22 0 q6 20 3 38 q-14 6 -28 0 q-3 -18 3 -38 Z" fill={P.shirt} />
          <path d="M-9 -95 q9 -4 18 0 q2 8 1 14 q-10 4 -20 0 q-1 -6 1 -14 Z" fill={P.shirtShade} opacity="0.45" />
          <path d="M-3.5 -100 q3.5 -3 7 0 l1 6 q-4.5 3 -9 0 Z" fill={P.skin} />
          <path d="M-8 -92 q8 5 16 0 q1 4 -2 6 q-6 4 -12 0 q-3 -2 -2 -6 Z" fill={P.scarf} opacity="0.9" />
        </g>

        {/* head: static wrapper puts the animated group's origin at the neck */}
        <g transform="translate(0 -100)">
          <g className="walk-head">
            <circle cx="0" cy="-12" r="12.4" fill={P.skin} />
            <path d="M-12.4 -14 q-1 -13 12.4 -13 q13.4 0 12.4 13 q-4 -7 -12.4 -7 q-8.4 0 -12.4 7 Z" fill={P.hair} />
            <path d="M-11.5 -11 q3 -6 6 -7" stroke={P.hair} strokeWidth="2.6" fill="none" strokeLinecap="round" />
          </g>
        </g>

        <Leg side="near" />
        <Arm side="near" />
      </g>
    </g>

    {/* Foreground grass — the fastest band, closest to the viewer. */}
    <g className="walk-band walk-band--foreground">
      <Tile width={200}>
        <path
          d={`M0 ${GROUND + 38} q30 -22 46 -4 q22 -18 38 2 q26 -20 44 0 q24 -16 40 4 L168 420 L0 420 Z`}
          fill={P.meadowDeep}
          opacity="0.95"
        />
        <Tuft x={40} y={GROUND + 52} s={1.1} fill={P.meadowDeep} />
        <Tuft x={130} y={GROUND + 46} s={0.95} fill={P.meadowDeep} />
      </Tile>
    </g>
  </svg>
);

export default WalkingScene;
